import { getValidAccessToken } from '@/lib/tiktok';

export default async function handler(req, res) {
  // キャッシュ無効化
  res.setHeader('Cache-Control', 'no-store');

  const accessToken = await getValidAccessToken();

  if (!accessToken) {
    return res.status(401).json({
      error: '未認証',
      message: '/api/tiktok/auth にアクセスしてTikTokアカウントと連携してください',
    });
  }

  const videoRes = await fetch(
    'https://open.tiktokapis.com/v2/video/list/?fields=id,title,embed_html,cover_image_url',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ max_count: 3 }),
    }
  );

  const data = await videoRes.json();

  if (data.error?.code && data.error.code !== 'ok') {
    return res.status(500).json({ error: data.error });
  }

  const videos = data.data?.videos || [];
  res.json({ videos });
}
